<script setup>
import {computed,onMounted,onUnmounted,ref} from 'vue'
import {api} from './api'
const props=defineProps({section:String,token:String,language:String,snapshot:Object,idle:Boolean})
const emit=defineEmits(['dirty'])
const tr=(ru,uz,en)=>({ru,uz,en}[props.language]||ru)
const data=ref(null),busy=ref(false),error=ref(''),notice=ref(''),confirmation=ref(''),offlineCode=ref(''),filter=ref('all'),payments=ref([]),summary=ref([]),cursor=ref(null),more=ref(false)
const request=(path,options={})=>api('/api/admin/'+path,{token:props.token,...options})
const n=v=>Number(v||0).toLocaleString(props.language==='ru'?'ru-RU':'en-US')
const bytes=v=>Number(v||0)>=1024**3?(Number(v)/1024**3).toFixed(1)+' GB':(Number(v||0)/1024**2).toFixed(1)+' MB'
const stamp=v=>v?new Date(v).toLocaleString('ru-RU',{timeZone:'Asia/Tashkent'}):'—'
const yes=v=>v?tr('Да','Ha','Yes'):tr('Нет','Yo‘q','No')
const states={local_pending:['Создан','Yaratilgan','Created'],pending:['Ожидает оплаты','To‘lov kutilmoqda','Awaiting payment'],prepared:['Подготовлен','Tayyorlangan','Prepared'],paid:['Оплачен, не зачислен','To‘langan, hisobga olinmagan','Paid, not credited'],credited:['Зачислен','Hisobga olingan','Credited'],cancelled:['Отменён','Bekor qilingan','Cancelled'],expired:['Истёк','Muddati tugagan','Expired'],error:['Ошибка','Xato','Error'],valid:['Действует','Amalda','Valid'],enforcement_disabled:['Контроль отключён','Nazorat o‘chirilgan','Enforcement disabled'],not_configured:['Не настроена','Sozlanmagan','Not configured'],sync_error:['Ошибка связи','Aloqa xatosi','Connection error'],locked:['Заблокирована','Bloklangan','Locked']}
const label=k=>states[k]?tr(...states[k]):k||'—'
const rfidStates={not_checked:['Ещё не проверялась','Hali tekshirilmagan','Not checked yet'],online:['Считыватель на связи','O‘quvchi ulangan','Reader online'],offline:['Нет связи со считывателем','O‘quvchi bilan aloqa yo‘q','Reader offline'],card_rejected:['Карта заблокирована или отключена','Karta bloklangan yoki o‘chirilgan','Card blocked or disabled'],customer_balance_saved:['Остаток сохранён на карту','Qoldiq kartaga saqlandi','Remaining credit saved to card'],customer_balance_used:['Баланс карты перенесён в сеанс','Karta balansi seansga o‘tkazildi','Card balance moved to session'],customer_card_seen:['Карта прочитана','Karta o‘qildi','Card read'],vip_profile_disabled:['VIP-профиль отключён','VIP profil o‘chirilgan','VIP profile disabled'],vip_daily_limit:['Дневной лимит VIP исчерпан','VIP kunlik limiti tugagan','VIP daily limit reached'],vip_empty_grant:['В VIP-профиле не задано время','VIP profilida vaqt yo‘q','VIP profile grants no time'],vip_granted:['VIP-сеанс открыт','VIP seansi ochildi','VIP session started'],vip_session_active:['VIP-сеанс уже активен','VIP seansi faol','VIP session already active'],vip_session_closed:['VIP-сеанс закрыт','VIP seansi yopildi','VIP session closed'],vip_remaining_burned:['Остаток VIP завершён','VIP qoldig‘i yakunlandi','VIP remainder ended'],customer_balance_changed:['Баланс карты изменился','Karta balansi o‘zgardi','Card balance changed']}
const result=computed(()=>{const r=props.snapshot?.state?.lastRfidResult;return rfidStates[r]?tr(...rfidStates[r]):r||'—'})
const license=computed(()=>data.value?.license||{}),hardware=computed(()=>data.value?.hardware||{})
const count=status=>summary.value.filter(r=>status.includes(r.status)).reduce((a,r)=>a+Number(r.count),0)
async function loadPayments(older=false){const q=new URLSearchParams({status:filter.value,limit:30,...(older?cursor.value:{})});const r=await request('service/click-payments?'+q);payments.value=older?[...payments.value,...r.intents]:r.intents;summary.value=r.summary;cursor.value=r.next_cursor;more.value=r.has_more}
async function load(){if(props.section==='storage')data.value=await request('service/storage');else if(['license','hardware','click'].includes(props.section)){data.value=await request('install/status');if(props.section==='click')await loadPayments()}}
async function run(fn){if(busy.value)return;busy.value=true;error.value='';try{await fn()}catch(e){error.value=e.message}finally{busy.value=false}}
async function act(){const action=confirmation.value;if(!action)return;await request(action,{method:'POST',body:JSON.stringify(action==='license/offline-code'?{code:offlineCode.value}:{})});if(action==='license/offline-code'){offlineCode.value='';emit('dirty',false)}confirmation.value='';notice.value=tr('Запрос выполнен','So‘rov bajarildi','Request completed');await load()}
let timer;onMounted(()=>{run(load);if(props.section==='storage')timer=setInterval(()=>{if(!document.hidden)run(load)},60000)});onUnmounted(()=>clearInterval(timer))
</script>
<template>
<div v-if="error" class="message error" role="alert">{{ error }}</div><div v-if="notice" class="message success" role="status">{{ notice }}</div>
<section v-if="section==='rfid'" class="card content"><h2>{{ tr('Обработка карты движком','Dvigatelda kartani qayta ishlash','Card processing by engine') }}</h2><p class="muted">{{ tr('Чтение PN532 и результат обработки — отдельные этапы. Последний результат сохраняется до следующего события карты или перезапуска.','PN532 o‘qishi va qayta ishlash natijasi alohida bosqichlar. Natija keyingi karta yoki qayta ishga tushirishgacha saqlanadi.','PN532 reading and processing are separate stages. The last result remains until the next card event or restart.') }}</p><dl class="detail-list"><div><dt>{{ tr('Обработанный UID','Qayta ishlangan UID','Processed UID') }}</dt><dd>{{ snapshot?.state.lastRfidUid||'—' }}</dd></div><div><dt>{{ tr('Результат','Natija','Result') }}</dt><dd>{{ result }}</dd></div><div><dt>{{ tr('Время события','Voqea vaqti','Event time') }}</dt><dd>{{ stamp(snapshot?.state.lastRfidProcessedAt) }}</dd></div><div><dt>{{ tr('Активная карта / сеанс','Faol karta / seans','Active card / session') }}</dt><dd>{{ snapshot?.state.activeSessionCardUid||'—' }} / {{ snapshot?.state.activeSessionId||'—' }}</dd></div></dl></section>
<section v-if="section==='hardware' && data" class="card content"><h2>{{ tr('Привязка платы и microSD','Plata va microSD bog‘lanishi','Board and microSD identity') }}</h2><dl class="detail-list"><div><dt>{{ tr('Идентификатор полный','Identifikator to‘liq','Identity complete') }}</dt><dd>{{ yes(hardware.complete) }}</dd></div><div><dt>{{ tr('Плата обнаружена','Plata topildi','Board detected') }}</dt><dd>{{ yes(hardware.wlan0_mac_present) }} · {{ hardware.wlan0_mac_tail||'—' }}</dd></div><div><dt>microSD</dt><dd>{{ yes(hardware.microsd_cid_present) }} · {{ hardware.microsd_cid_tail||'—' }}</dd></div><div><dt>Fingerprint</dt><dd>{{ hardware.hardware_fingerprint_hash||'—' }}</dd></div><div><dt>{{ tr('Привязка подтверждена сервером','Bog‘lanish serverda tasdiqlangan','Binding confirmed by server') }}</dt><dd>{{ yes(license.hardware_bound) }}</dd></div><div><dt>{{ tr('Состояние активации','Aktivatsiya holati','Activation status') }}</dt><dd>{{ license.activation_status||'—' }}</dd></div></dl><p class="muted">{{ tr('Активация и замена microSD выполняются через «Установку поста». Изменение номера поста само по себе не подтверждает новую привязку.','Aktivatsiya va microSD almashtirish postni o‘rnatish orqali bajariladi. Post raqamini o‘zgartirish yangi bog‘lanishni tasdiqlamaydi.','Activation and microSD replacement use Station setup. Changing the station number does not approve a new binding.') }}</p></section>
<template v-if="section==='license' && data"><section class="card content"><h2>{{ tr('Состояние лицензии','Litsenziya holati','License status') }}</h2><dl class="detail-list"><div><dt>{{ tr('Состояние','Holat','State') }}</dt><dd>{{ label(license.state) }}</dd></div><div><dt>{{ tr('Мойка заблокирована','Yuvish bloklangan','Wash locked') }}</dt><dd>{{ yes(license.locked) }}</dd></div><div><dt>{{ tr('Причина решения','Qaror sababi','Decision reason') }}</dt><dd>{{ license.reason||'—' }}</dd></div><div><dt>{{ tr('Режим / тип лицензии','Rejim / litsenziya turi','Mode / license type') }}</dt><dd>{{ license.operation_mode||'—' }} / {{ license.license_duration_type||'—' }}</dd></div><div><dt>{{ tr('Действует до / дней осталось','Amal qilish muddati / qolgan kun','Valid until / days left') }}</dt><dd>{{ stamp(license.valid_until) }} / {{ license.days_left??'—' }}</dd></div><div><dt>{{ tr('Последняя успешная проверка','Oxirgi muvaffaqiyatli tekshiruv','Last successful check') }}</dt><dd>{{ stamp(license.last_success_at) }}</dd></div><div><dt>{{ tr('Последняя попытка','Oxirgi urinish','Last attempt') }}</dt><dd>{{ stamp(license.last_attempt_at) }}</dd></div><div><dt>{{ tr('Следующая проверка','Keyingi tekshiruv','Next check') }}</dt><dd>{{ stamp(license.next_sync_at) }}</dd></div><div><dt>{{ tr('Рекомендуемая синхронизация до','Tavsiya etilgan sinxronlash muddati','Recommended sync deadline') }}</dt><dd>{{ stamp(license.grace_until) }}</dd></div><div><dt>{{ tr('Ошибка синхронизации','Sinxronlash xatosi','Synchronization error') }}</dt><dd>{{ license.last_error||'—' }}</dd></div></dl><div class="actions"><button class="quiet" :disabled="busy" @click="run(load)">{{ tr('Обновить состояние','Holatni yangilash','Refresh status') }}</button><button class="primary" :disabled="busy||!idle||!data.license_settings.site_code" @click="confirmation='license/sync'">{{ tr('Проверить на сервере','Serverda tekshirish','Check with server') }}</button></div><p v-if="!idle" class="muted">{{ tr('Сначала завершите текущий сеанс.','Avval joriy seansni yakunlang.','Finish the current session first.') }}</p></section><form class="card content" @submit.prevent="confirmation='license/offline-code'"><h2>{{ tr('Офлайн-код','Oflayn kod','Offline code') }}</h2><label>{{ tr('Подписанный код лицензии','Imzolangan litsenziya kodi','Signed license code') }}<input v-model.trim="offlineCode" @input="emit('dirty',!!offlineCode)" minlength="20" maxlength="1200" required autocomplete="off" /></label><button class="primary" style="margin-top:20px" :disabled="busy||!idle||!offlineCode">{{ tr('Применить код','Kodni qo‘llash','Apply code') }}</button></form></template>
<template v-if="section==='click' && data"><div class="metrics"><section class="card metric"><p>Click</p><strong>{{ data.click_settings.enabled?tr('Включён','Yoqilgan','Enabled'):tr('Отключён','O‘chirilgan','Disabled') }}</strong></section><section class="card metric"><p>{{ tr('Ожидают оплаты','To‘lov kutilmoqda','Awaiting payment') }}</p><strong>{{ n(count(['local_pending','pending','prepared'])) }}</strong></section><section class="card metric"><p>{{ tr('Оплачены, не зачислены','To‘langan, hisobga olinmagan','Paid, not credited') }}</p><strong>{{ n(count(['paid'])) }}</strong></section><section class="card metric"><p>{{ tr('Зачислены','Hisobga olingan','Credited') }}</p><strong>{{ n(count(['credited'])) }}</strong></section></div><p class="muted">{{ tr('История — 12 месяцев. Незавершённые платежи сохраняются дольше до разрешения. Настройки Click находятся в «Подключении».','Tarix — 12 oy. Tugallanmagan to‘lovlar hal bo‘lguncha saqlanadi. Click sozlamalari «Ulanish»da.','History: 12 months. Unresolved payments remain longer. Click settings are under Connection.') }}</p><section class="card"><div class="card-head admin-section-head"><label>{{ tr('Статус платежа','To‘lov holati','Payment status') }}<select v-model="filter" :disabled="busy" @change="run(()=>loadPayments())"><option value="all">{{ tr('Все','Barchasi','All') }}</option><option v-for="key in ['local_pending','pending','prepared','paid','credited','cancelled','expired','error']" :value="key">{{ label(key) }}</option></select></label><div class="actions"><button class="quiet" :disabled="busy" @click="run(()=>loadPayments())">{{ tr('Обновить платежи','To‘lovlarni yangilash','Refresh payments') }}</button><button class="primary" :disabled="busy||!data.click_settings.enabled" @click="confirmation='click/sync'">{{ tr('Синхронизировать Click','Clickni sinxronlash','Synchronize Click') }}</button></div></div><div class="table-wrap"><table><thead><tr><th>{{ tr('Создан / ID','Yaratilgan / ID','Created / ID') }}</th><th>{{ tr('Сумма','Summa','Amount') }}</th><th>{{ tr('Статус','Holat','Status') }}</th><th>{{ tr('Оплачен / зачислен','To‘langan / hisobga olingan','Paid / credited') }}</th><th>{{ tr('Сервер / ошибка','Server / xato','Server / error') }}</th></tr></thead><tbody><tr v-for="p in payments" :key="p.id"><td>{{ stamp(p.created_at) }}<small class="cell-note">{{ p.id }}</small></td><td>{{ n(p.amount_sum) }}</td><td>{{ label(p.status) }}</td><td>{{ stamp(p.paid_at) }}<small class="cell-note">{{ stamp(p.credited_at) }}</small></td><td>{{ p.gateway_status||'—' }}<small class="cell-note">{{ p.last_error||'' }}</small></td></tr></tbody></table></div><p v-if="!payments.length" class="empty">{{ tr('Платежей нет','To‘lovlar yo‘q','No payments') }}</p><div class="content actions end"><button v-if="more" class="quiet" :disabled="busy" @click="run(()=>loadPayments(true))">{{ tr('Показать более ранние','Oldingilarini ko‘rsatish','Load earlier payments') }}</button></div></section></template>
<section v-if="section==='storage' && data" class="card content"><h2>{{ tr('Память и хранение данных','Xotira va ma’lumotlarni saqlash','Storage and retention') }}</h2><div v-if="data.level!=='ok'" class="message error" role="alert">{{ data.level==='critical'?tr('Критически мало свободного места. Требуется обслуживание.','Bo‘sh joy juda kam. Xizmat talab qilinadi.','Critically low disk space. Service required.'):tr('Свободного места мало. Проверьте накопитель и журналы.','Bo‘sh joy kam. Disk va jurnallarni tekshiring.','Low disk space. Check storage and logs.') }}</div><dl class="detail-list"><div><dt>{{ tr('Свободно / всего','Bo‘sh / jami','Free / total') }}</dt><dd>{{ bytes(data.disk_free_bytes) }} / {{ bytes(data.disk_total_bytes) }} · {{ data.free_percent }}%</dd></div><div><dt>{{ tr('Размер базы','Baza hajmi','Database size') }}</dt><dd>{{ bytes(data.database_bytes) }}</dd></div><div><dt>{{ tr('Событий в базе','Bazadagi voqealar','Stored events') }}</dt><dd>{{ n(data.events.count) }}</dd></div><div><dt>{{ tr('Финансовая история','Moliyaviy tarix','Financial history') }}</dt><dd>{{ data.retention.financial_months }} {{ tr('месяцев','oy','months') }}</dd></div><div><dt>{{ tr('События / технические журналы','Voqealar / texnik jurnallar','Events / technical logs') }}</dt><dd>{{ data.retention.event_months }} {{ tr('месяц','oy','month') }} · {{ data.retention.journal_limit_mb }} MB {{ tr('лимит журналов','jurnal limiti','log limit') }}</dd></div><div><dt>{{ tr('Последняя очистка','Oxirgi tozalash','Last cleanup') }}</dt><dd>{{ stamp(data.retention.last_run?.last_run_at) }}</dd></div><div><dt>{{ tr('Защищённые остатки','Himoyalangan qoldiqlar','Protected credit') }}</dt><dd>{{ n(data.protected_credit.amount_sum) }} {{ tr('сум, без удаления по возрасту','so‘m, muddatsiz','sum, no age-based deletion') }}</dd></div></dl><div v-if="data.retention.last_run?.ok===false" class="message error" role="alert">{{ tr('Очистка не завершена. Данные сохранены; повторная попытка автоматически.','Tozalash tugamadi. Ma’lumot saqlandi; qayta urinish avtomatik.','Cleanup failed. Data was preserved; retry is automatic.') }} {{ data.retention.last_run.error }}</div><p class="muted">{{ tr('Очистка базы — каждый час, журналов — ежедневно. При достижении лимита старые технические логи удаляются раньше месяца. Балансы карт и невостребованные остатки не удаляются по сроку.','Baza har soat, jurnallar har kuni tozalanadi. Limitda eski texnik jurnallar bir oydan oldin o‘chiriladi. Karta balansi va talab qilinmagan qoldiqlar saqlanadi.','Database cleanup runs hourly, log cleanup daily. At the size limit, old technical logs expire earlier. Card balances and unclaimed credit never expire by age.') }}</p></section>
<div v-if="confirmation" class="confirm-backdrop"><section class="card confirm-dialog" role="alertdialog" aria-modal="true"><h2>{{ tr('Выполнить действие?','Amal bajarilsinmi?','Perform this action?') }}</h2><p>{{ confirmation==='click/sync'?tr('Подтверждённые сервером платежи могут быть зачислены в текущий сеанс.','Server tasdiqlagan to‘lovlar joriy seansga tushishi mumkin.','Server-confirmed payments may be credited to the current session.'):tr('Проверка лицензии может изменить доступность мойки.','Litsenziya tekshiruvi yuvish imkoniyatini o‘zgartirishi mumkin.','License verification may change wash availability.') }}</p><div v-if="error" class="message error">{{ error }}</div><div class="actions"><button class="quiet" :disabled="busy" @click="confirmation=''">{{ tr('Отмена','Bekor qilish','Cancel') }}</button><button class="primary" :disabled="busy||(confirmation!=='click/sync'&&!idle)" @click="run(act)">{{ tr('Подтвердить','Tasdiqlash','Confirm') }}</button></div></section></div>
</template>
